implementation:
#include <string.h>
#include <stdlib.h>

#include "magick.h"

size_t RegisterJPEGImage(void) {
  static const char *jpeg_version = "6b";
  static MagickInfo *magick_info = NULL;
  static const char *jpeg_mime_type = "image/jpeg";
  static const char *jpeg_extensions[] = {"JPE", "JPEG", "JPG", "JPS", "PJPEG"};
  size_t count = sizeof(jpeg_extensions) / sizeof(jpeg_extensions[0]);

  magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(*magick_info));
  if (!magick_info)
    return 0;

  (void) memset(magick_info, 0, sizeof(*magick_info));
  magick_info->decoder = JPEGDecoder;
  magick_info->encoder = JPEGEncoder;
  magick_info->thread_support = MagickTrue;
  magick_info->mime_type = (char *) AcquireString(jpeg_mime_type);

  for (size_t i = 0; i < count; ++i) {
    MagickInfo *entry = (MagickInfo *) AcquireMagickMemory(sizeof(*entry));
    if (!entry) {
      for (size_t j = 0; j < i; ++j)
        RelinquishMagickMemory(entry);
      RelinquishMagickMemory(magick_info);
      return 0;
    }

    (void) memset(entry, 0, sizeof(*entry));
    entry->decoder = magick_info->decoder;
    entry->encoder = magick_info->encoder;
    entry->thread_support = magick_info->thread_support;
    entry->mime_type = (char *) AcquireString(magick_info->mime_type);

    char *identifier = (char *) AcquireString(jpeg_extensions[i]);
    if (!identifier) {
      RelinquishMagickMemory(entry);
      continue;
    }

    entry->name = identifier;

    if (!SetMagickInfo(entry)) {
      RelinquishMagickMemory(entry);
      RelinquishMagickMemory(identifier);
      continue;
    }

    if (!RegisterMagickInfo(entry)) {
      RelinquishMagickMemory(entry);
      RelinquishMagickMemory(identifier);
      continue;
    }
  }

  RelinquishMagickMemory(magick_info->mime_type);
  RelinquishMagickMemory(magick_info);

  return count;
}
